contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash, uint amount) public payable {
        require(address(this).balance >= amount);

        bool firstReverted;
        try c.lockInGuess{value: amount}(hash) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool secondReverted;
        try c.lockInGuess{value: amount}(hash) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(firstReverted == (amount != 1 ether) && (!firstReverted || secondReverted));
    }

    receive() external payable {}
}

