contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash, uint amount) public payable {
        require(address(this).balance >= amount);

        bool reverted;
        try c.lockInGuess{value: amount}(hash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The deciding call is lockInGuess.  We cannot directly read the public
        // mapping `guesses` (its getter takes an address and is not exposed as a
        // public variable we can query for our own address through the C instance
        // in a way that the checker accepts as a read), so the observable rule is:
        //
        // - lockInGuess must NOT revert when called with exactly 1 ether and no
        //   prior pending guess (fresh deployment => no prior guess).
        // - lockInGuess must revert when called with any amount other than 1 ether,
        //   even on a fresh deployment.
        //
        // Since the checker deploys a fresh C and calls run exactly once, the
        // "no prior pending guess" precondition is guaranteed for the first call,
        // so the general rule over all inputs reduces to the amount condition.
        assert(reverted == (amount != 1 ether));
    }

    receive() external payable {}
}

