contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guessHash) public payable {
        require(address(this).balance >= 1 ether);
        c.lockInGuess{value: 1 ether}(guessHash);

        uint256 guessBlockBefore = block.number + 1;
        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 guessBlockAfter = guessBlockBefore;
        uint256 cBalanceAfter = address(c).balance;

        assert(reverted == false && cBalanceAfter == cBalanceBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guessHash) public payable {
        require(address(this).balance >= 1 ether);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Since lockInGuess set guesses[msg.sender].block = block.number + 1,
        // settle() requires block.number > guesses[msg.sender].block, which
        // cannot be true in the same transaction.  Therefore settle() must
        // revert in this transaction.  We try it and assert on the revert flag.
        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == true);
    }

    receive() external payable {}
}

